#!/usr/bin/env python3
"""Small background cues behind the unchanged main avatar; semantic review pending."""
from pathlib import Path
import json,xml.etree.ElementTree as ET
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'assets/emma-background-cues';OUT.mkdir(exist_ok=True)
heart='M0 14 C-30-7-37-27-21-36 C-10-44-1-36 0-31 C10-47 36-40 31-21 C28-8 11 8 0 14Z'
star='M0-30 9-10 31-8 15 7 19 30 0 18-20 30-15 7-32-8-10-10Z'
entries=[];sources={}
for key,label,shape,color,locations in [
 ('calm','安心：ハート案',heart,'#e891ac',[(64,90,.7),(449,86,.8),(60,450,.6)]),
 ('celebrate','ほめる：星案',star,'#efbd55',[(59,88,.8),(450,88,.8),(451,453,.6)])]:
 items=''.join(f'<g transform="translate({x} {y}) scale({s})"><g class="eb-symbol eb-{i}"><path d="{shape}" fill="url(#eb-{key}-paint)" stroke="{color}" stroke-width="1.6"/></g></g>' for i,(x,y,s) in enumerate(locations))
 css=f'[data-emma-backdrop="{key}"] .eb-symbol{{transform-origin:0 0;animation:eb-{key}-float 4.8s ease-in-out infinite}}[data-emma-backdrop="{key}"] .eb-1{{animation-delay:-1.6s}}[data-emma-backdrop="{key}"] .eb-2{{animation-delay:-3.2s}}@keyframes eb-{key}-float{{0%,100%{{transform:translateY(0);opacity:.8}}50%{{transform:translateY(-10px);opacity:1}}}}@media(prefers-reduced-motion:reduce){{.eb-symbol{{animation:none!important}}}}[data-motion="off"] .eb-symbol{{animation:none!important}}'
 svg=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" data-emma-backdrop="{key}" aria-hidden="true"><style>{css}</style><defs><radialGradient id="eb-{key}-halo"><stop stop-color="{color}" stop-opacity=".22"/><stop offset="1" stop-color="{color}" stop-opacity="0"/></radialGradient><linearGradient id="eb-{key}-paint" x2=".5" y2="1"><stop stop-color="{color}"/><stop offset="1" stop-color="{color}" stop-opacity=".7"/></linearGradient></defs><ellipse cx="256" cy="246" rx="245" ry="240" fill="url(#eb-{key}-halo)"/>{items}</svg>'''
 ET.fromstring(svg);poster=svg.replace('data-emma-backdrop=', 'data-motion="off" data-emma-backdrop=',1)
 (OUT/f'{key}.svg').write_text(svg+'\n');(OUT/f'{key}-poster.svg').write_text(poster+'\n');sources[key]=svg
 entries.append(dict(id=key,label=label,status='candidate',meaningReview='user-review-pending; hearts/stars are supplementary and do not assert a specific feeling',animation=f'assets/emma-background-cues/{key}.svg',poster=f'assets/emma-background-cues/{key}-poster.svg'))
(OUT/'manifest.json').write_text(json.dumps(dict(schemaVersion=1,avatar='Existing main face, blinking and audio-driven mouth remain unchanged.',candidates=entries,baselineOnlyStates=['neutral','smile','listen','ask','invite']),ensure_ascii=False,indent=2)+'\n')
(ROOT/'src/emma-background-cues.js').write_text('// Generated by build_emma_backgrounds.py; two semantic candidates, no avatar replacement.\nexport const EMMA_BACKGROUND_CUES='+json.dumps(sources,ensure_ascii=False)+';\nlet instance=0;\nexport function createEmmaBackground(state,document=globalThis.document){let svg=EMMA_BACKGROUND_CUES[state];if(!svg)return null;svg=svg.replaceAll("eb-"+state+"-","eb-"+state+"-"+(++instance)+"-");const template=document.createElement("template");template.innerHTML=svg;return template.content.firstElementChild;}\n')
print('Built two supplementary background candidates; five states retain baseline Emma.')
